    logic [$bits(sram_axi_rid_bridge_id)-1:0] xs_sram_axi_rid_bridge_id;
    logic [$bits(sram_axi_rid)-1:0] xs_sram_axi_rid;
    logic [$bits(sram_axi_rdata)-1:0] xs_sram_axi_rdata;
    logic [$bits(sram_axi_rresp)-1:0] xs_sram_axi_rresp;
    logic [$bits(sram_axi_rlast)-1:0] xs_sram_axi_rlast;
    logic [$bits(sram_axi_ruser)-1:0] xs_sram_axi_ruser;
    logic xs_sram_axi_rvalid;
    logic xs_sram_axi_rready;
    logic xs_sram_axi_bid_valid;
    logic xs_sram_axi_rid_valid;
    logic [$bits(subtractive_axi_awid)-1:0] xs_subtractive_axi_awid;
    logic [$bits(subtractive_axi_awaddr)-1:0] xs_subtractive_axi_awaddr;
    logic [$bits(subtractive_axi_awlen)-1:0] xs_subtractive_axi_awlen;
    logic [$bits(subtractive_axi_awsize)-1:0] xs_subtractive_axi_awsize;
    logic [$bits(subtractive_axi_awburst)-1:0] xs_subtractive_axi_awburst;
    logic [$bits(subtractive_axi_awlock)-1:0] xs_subtractive_axi_awlock;
    logic [$bits(subtractive_axi_awcache)-1:0] xs_subtractive_axi_awcache;
    logic [$bits(subtractive_axi_awprot)-1:0] xs_subtractive_axi_awprot;
    logic [$bits(subtractive_axi_awqos)-1:0] xs_subtractive_axi_awqos;
    logic [$bits(subtractive_axi_awregion)-1:0] xs_subtractive_axi_awregion;
    logic [$bits(subtractive_axi_awuser)-1:0] xs_subtractive_axi_awuser;
    logic [$bits(subtractive_axi_bridge_id_aw)-1:0] xs_subtractive_axi_bridge_id_aw;
    logic xs_subtractive_axi_awvalid;
    logic xs_subtractive_axi_awready;
    logic [$bits(subtractive_axi_wdata)-1:0] xs_subtractive_axi_wdata;
    logic [$bits(subtractive_axi_wstrb)-1:0] xs_subtractive_axi_wstrb;
    logic [$bits(subtractive_axi_wlast)-1:0] xs_subtractive_axi_wlast;
    logic [$bits(subtractive_axi_wuser)-1:0] xs_subtractive_axi_wuser;
    logic xs_subtractive_axi_wvalid;
    logic xs_subtractive_axi_wready;
    logic [$bits(subtractive_axi_arid)-1:0] xs_subtractive_axi_arid;
    logic [$bits(subtractive_axi_araddr)-1:0] xs_subtractive_axi_araddr;
    logic [$bits(subtractive_axi_arlen)-1:0] xs_subtractive_axi_arlen;
    logic [$bits(subtractive_axi_arsize)-1:0] xs_subtractive_axi_arsize;
    logic [$bits(subtractive_axi_arburst)-1:0] xs_subtractive_axi_arburst;
    logic [$bits(subtractive_axi_arlock)-1:0] xs_subtractive_axi_arlock;
    logic [$bits(subtractive_axi_arcache)-1:0] xs_subtractive_axi_arcache;
    logic [$bits(subtractive_axi_arprot)-1:0] xs_subtractive_axi_arprot;
    logic [$bits(subtractive_axi_arqos)-1:0] xs_subtractive_axi_arqos;
    logic [$bits(subtractive_axi_arregion)-1:0] xs_subtractive_axi_arregion;
    logic [$bits(subtractive_axi_aruser)-1:0] xs_subtractive_axi_aruser;
    logic [$bits(subtractive_axi_bridge_id_ar)-1:0] xs_subtractive_axi_bridge_id_ar;
    logic xs_subtractive_axi_arvalid;
    logic xs_subtractive_axi_arready;
    logic [$bits(subtractive_axi_bid_bridge_id)-1:0] xs_subtractive_axi_bid_bridge_id;
    logic [$bits(subtractive_axi_bid)-1:0] xs_subtractive_axi_bid;
    logic [$bits(subtractive_axi_bresp)-1:0] xs_subtractive_axi_bresp;
    logic [$bits(subtractive_axi_buser)-1:0] xs_subtractive_axi_buser;
    logic xs_subtractive_axi_bvalid;
    logic xs_subtractive_axi_bready;
    logic [$bits(subtractive_axi_rid_bridge_id)-1:0] xs_subtractive_axi_rid_bridge_id;
    logic [$bits(subtractive_axi_rid)-1:0] xs_subtractive_axi_rid;
    logic [$bits(subtractive_axi_rdata)-1:0] xs_subtractive_axi_rdata;
    logic [$bits(subtractive_axi_rresp)-1:0] xs_subtractive_axi_rresp;
    logic [$bits(subtractive_axi_rlast)-1:0] xs_subtractive_axi_rlast;
    logic [$bits(subtractive_axi_ruser)-1:0] xs_subtractive_axi_ruser;
    logic xs_subtractive_axi_rvalid;
    logic xs_subtractive_axi_rready;
    logic xs_subtractive_axi_bid_valid;
    logic xs_subtractive_axi_rid_valid;

    // ================================================================
    // Response arbiters (one slave per master path per channel)
    // ================================================================

    // ---- B response arbiter, master cpu 32b: round-robin per beat, lock until taken ----
    logic [2:0] cpu_32b_b_rarb_req;
    assign cpu_32b_b_rarb_req = {((xs_subtractive_axi_bid_bridge_id == 0) && xs_subtractive_axi_bid_valid) && xs_subtractive_axi_bvalid, ((xs_sram_axi_bid_bridge_id == 0) && xs_sram_axi_bid_valid) && xs_sram_axi_bvalid, ((xs_ddr_axi_bid_bridge_id == 0) && xs_ddr_axi_bid_valid) && xs_ddr_axi_bvalid};
    logic [1:0] cpu_32b_b_rarb_lock, cpu_32b_b_rarb_rr;
    logic cpu_32b_b_rarb_locked;
    wire [1:0] cpu_32b_b_rarb_pick = (cpu_32b_b_rarb_rr == 2'd0) ? (cpu_32b_b_rarb_req[0] ? 2'd0 : cpu_32b_b_rarb_req[1] ? 2'd1 : 2'd2) : 
        (cpu_32b_b_rarb_rr == 2'd1) ? (cpu_32b_b_rarb_req[1] ? 2'd1 : cpu_32b_b_rarb_req[2] ? 2'd2 : 2'd0) : 
        cpu_32b_b_rarb_req[2] ? 2'd2 : cpu_32b_b_rarb_req[0] ? 2'd0 : 2'd1;
    wire [1:0] cpu_32b_b_rarb_gnt = cpu_32b_b_rarb_locked ? cpu_32b_b_rarb_lock : cpu_32b_b_rarb_pick;
    wire cpu_32b_b_rarb_gnt_valid = cpu_32b_b_rarb_locked || (|cpu_32b_b_rarb_req);
    wire cpu_32b_b_rgnt_ddr = cpu_32b_b_rarb_gnt_valid && (cpu_32b_b_rarb_gnt == 2'd0);
    wire cpu_32b_b_rgnt_sram = cpu_32b_b_rarb_gnt_valid && (cpu_32b_b_rarb_gnt == 2'd1);
    wire cpu_32b_b_rgnt_subtractive = cpu_32b_b_rarb_gnt_valid && (cpu_32b_b_rarb_gnt == 2'd2);
    wire cpu_32b_b_rarb_vld = (cpu_32b_b_rgnt_ddr && cpu_32b_b_rarb_req[0]) || (cpu_32b_b_rgnt_sram && cpu_32b_b_rarb_req[1]) || (cpu_32b_b_rgnt_subtractive && cpu_32b_b_rarb_req[2]);
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            cpu_32b_b_rarb_lock   <= '0;
            cpu_32b_b_rarb_rr     <= '0;
            cpu_32b_b_rarb_locked <= 1'b0;
        end else if (cpu_32b_b_rarb_vld && cpu_32b_bready) begin
            cpu_32b_b_rarb_locked <= 1'b0;
            cpu_32b_b_rarb_rr <= (cpu_32b_b_rarb_gnt == 2'd2) ? 2'd0 : cpu_32b_b_rarb_gnt + 1'b1;
        end else if (cpu_32b_b_rarb_vld) begin
            cpu_32b_b_rarb_lock   <= cpu_32b_b_rarb_gnt;       // offered, not taken: hold
            cpu_32b_b_rarb_locked <= 1'b1;
        end
    )

    // ---- R response arbiter, master cpu 32b: round-robin per beat, lock until taken ----
    logic [2:0] cpu_32b_r_rarb_req;
    assign cpu_32b_r_rarb_req = {((xs_subtractive_axi_rid_bridge_id == 0) && xs_subtractive_axi_rid_valid) && xs_subtractive_axi_rvalid, ((xs_sram_axi_rid_bridge_id == 0) && xs_sram_axi_rid_valid) && xs_sram_axi_rvalid, ((xs_ddr_axi_rid_bridge_id == 0) && xs_ddr_axi_rid_valid) && xs_ddr_axi_rvalid};
    logic [1:0] cpu_32b_r_rarb_lock, cpu_32b_r_rarb_rr;
    logic cpu_32b_r_rarb_locked;
    wire [1:0] cpu_32b_r_rarb_pick = (cpu_32b_r_rarb_rr == 2'd0) ? (cpu_32b_r_rarb_req[0] ? 2'd0 : cpu_32b_r_rarb_req[1] ? 2'd1 : 2'd2) : 
        (cpu_32b_r_rarb_rr == 2'd1) ? (cpu_32b_r_rarb_req[1] ? 2'd1 : cpu_32b_r_rarb_req[2] ? 2'd2 : 2'd0) : 
        cpu_32b_r_rarb_req[2] ? 2'd2 : cpu_32b_r_rarb_req[0] ? 2'd0 : 2'd1;
    wire [1:0] cpu_32b_r_rarb_gnt = cpu_32b_r_rarb_locked ? cpu_32b_r_rarb_lock : cpu_32b_r_rarb_pick;
    wire cpu_32b_r_rarb_gnt_valid = cpu_32b_r_rarb_locked || (|cpu_32b_r_rarb_req);
    wire cpu_32b_r_rgnt_ddr = cpu_32b_r_rarb_gnt_valid && (cpu_32b_r_rarb_gnt == 2'd0);
    wire cpu_32b_r_rgnt_sram = cpu_32b_r_rarb_gnt_valid && (cpu_32b_r_rarb_gnt == 2'd1);
    wire cpu_32b_r_rgnt_subtractive = cpu_32b_r_rarb_gnt_valid && (cpu_32b_r_rarb_gnt == 2'd2);
    wire cpu_32b_r_rarb_vld = (cpu_32b_r_rgnt_ddr && cpu_32b_r_rarb_req[0]) || (cpu_32b_r_rgnt_sram && cpu_32b_r_rarb_req[1]) || (cpu_32b_r_rgnt_subtractive && cpu_32b_r_rarb_req[2]);
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            cpu_32b_r_rarb_lock   <= '0;
            cpu_32b_r_rarb_rr     <= '0;
            cpu_32b_r_rarb_locked <= 1'b0;
        end else if (cpu_32b_r_rarb_vld && cpu_32b_rready) begin
            cpu_32b_r_rarb_locked <= 1'b0;
            cpu_32b_r_rarb_rr <= (cpu_32b_r_rarb_gnt == 2'd2) ? 2'd0 : cpu_32b_r_rarb_gnt + 1'b1;
        end else if (cpu_32b_r_rarb_vld) begin
            cpu_32b_r_rarb_lock   <= cpu_32b_r_rarb_gnt;       // offered, not taken: hold
            cpu_32b_r_rarb_locked <= 1'b1;
        end
    )

    // ---- B response arbiter, master dma 32b: round-robin per beat, lock until taken ----
    logic [2:0] dma_32b_b_rarb_req;
    assign dma_32b_b_rarb_req = {((xs_subtractive_axi_bid_bridge_id == 1) && xs_subtractive_axi_bid_valid) && xs_subtractive_axi_bvalid, ((xs_sram_axi_bid_bridge_id == 1) && xs_sram_axi_bid_valid) && xs_sram_axi_bvalid, ((xs_ddr_axi_bid_bridge_id == 1) && xs_ddr_axi_bid_valid) && xs_ddr_axi_bvalid};
    logic [1:0] dma_32b_b_rarb_lock, dma_32b_b_rarb_rr;
    logic dma_32b_b_rarb_locked;
    wire [1:0] dma_32b_b_rarb_pick = (dma_32b_b_rarb_rr == 2'd0) ? (dma_32b_b_rarb_req[0] ? 2'd0 : dma_32b_b_rarb_req[1] ? 2'd1 : 2'd2) : 
        (dma_32b_b_rarb_rr == 2'd1) ? (dma_32b_b_rarb_req[1] ? 2'd1 : dma_32b_b_rarb_req[2] ? 2'd2 : 2'd0) : 
        dma_32b_b_rarb_req[2] ? 2'd2 : dma_32b_b_rarb_req[0] ? 2'd0 : 2'd1;
    wire [1:0] dma_32b_b_rarb_gnt = dma_32b_b_rarb_locked ? dma_32b_b_rarb_lock : dma_32b_b_rarb_pick;
    wire dma_32b_b_rarb_gnt_valid = dma_32b_b_rarb_locked || (|dma_32b_b_rarb_req);
    wire dma_32b_b_rgnt_ddr = dma_32b_b_rarb_gnt_valid && (dma_32b_b_rarb_gnt == 2'd0);
    wire dma_32b_b_rgnt_sram = dma_32b_b_rarb_gnt_valid && (dma_32b_b_rarb_gnt == 2'd1);
    wire dma_32b_b_rgnt_subtractive = dma_32b_b_rarb_gnt_valid && (dma_32b_b_rarb_gnt == 2'd2);
    wire dma_32b_b_rarb_vld = (dma_32b_b_rgnt_ddr && dma_32b_b_rarb_req[0]) || (dma_32b_b_rgnt_sram && dma_32b_b_rarb_req[1]) || (dma_32b_b_rgnt_subtractive && dma_32b_b_rarb_req[2]);
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            dma_32b_b_rarb_lock   <= '0;
            dma_32b_b_rarb_rr     <= '0;
            dma_32b_b_rarb_locked <= 1'b0;
        end else if (dma_32b_b_rarb_vld && dma_32b_bready) begin
            dma_32b_b_rarb_locked <= 1'b0;
            dma_32b_b_rarb_rr <= (dma_32b_b_rarb_gnt == 2'd2) ? 2'd0 : dma_32b_b_rarb_gnt + 1'b1;
        end else if (dma_32b_b_rarb_vld) begin
            dma_32b_b_rarb_lock   <= dma_32b_b_rarb_gnt;       // offered, not taken: hold
            dma_32b_b_rarb_locked <= 1'b1;
        end
    )

    // ---- R response arbiter, master dma 32b: round-robin per beat, lock until taken ----
    logic [2:0] dma_32b_r_rarb_req;
    assign dma_32b_r_rarb_req = {((xs_subtractive_axi_rid_bridge_id == 1) && xs_subtractive_axi_rid_valid) && xs_subtractive_axi_rvalid, ((xs_sram_axi_rid_bridge_id == 1) && xs_sram_axi_rid_valid) && xs_sram_axi_rvalid, ((xs_ddr_axi_rid_bridge_id == 1) && xs_ddr_axi_rid_valid) && xs_ddr_axi_rvalid};
    logic [1:0] dma_32b_r_rarb_lock, dma_32b_r_rarb_rr;
    logic dma_32b_r_rarb_locked;
    wire [1:0] dma_32b_r_rarb_pick = (dma_32b_r_rarb_rr == 2'd0) ? (dma_32b_r_rarb_req[0] ? 2'd0 : dma_32b_r_rarb_req[1] ? 2'd1 : 2'd2) : 
        (dma_32b_r_rarb_rr == 2'd1) ? (dma_32b_r_rarb_req[1] ? 2'd1 : dma_32b_r_rarb_req[2] ? 2'd2 : 2'd0) : 
        dma_32b_r_rarb_req[2] ? 2'd2 : dma_32b_r_rarb_req[0] ? 2'd0 : 2'd1;
    wire [1:0] dma_32b_r_rarb_gnt = dma_32b_r_rarb_locked ? dma_32b_r_rarb_lock : dma_32b_r_rarb_pick;
    wire dma_32b_r_rarb_gnt_valid = dma_32b_r_rarb_locked || (|dma_32b_r_rarb_req);
    wire dma_32b_r_rgnt_ddr = dma_32b_r_rarb_gnt_valid && (dma_32b_r_rarb_gnt == 2'd0);
    wire dma_32b_r_rgnt_sram = dma_32b_r_rarb_gnt_valid && (dma_32b_r_rarb_gnt == 2'd1);
    wire dma_32b_r_rgnt_subtractive = dma_32b_r_rarb_gnt_valid && (dma_32b_r_rarb_gnt == 2'd2);
    wire dma_32b_r_rarb_vld = (dma_32b_r_rgnt_ddr && dma_32b_r_rarb_req[0]) || (dma_32b_r_rgnt_sram && dma_32b_r_rarb_req[1]) || (dma_32b_r_rgnt_subtractive && dma_32b_r_rarb_req[2]);
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            dma_32b_r_rarb_lock   <= '0;
            dma_32b_r_rarb_rr     <= '0;
            dma_32b_r_rarb_locked <= 1'b0;
        end else if (dma_32b_r_rarb_vld && dma_32b_rready) begin
            dma_32b_r_rarb_locked <= 1'b0;
            dma_32b_r_rarb_rr <= (dma_32b_r_rarb_gnt == 2'd2) ? 2'd0 : dma_32b_r_rarb_gnt + 1'b1;
        end else if (dma_32b_r_rarb_vld) begin
            dma_32b_r_rarb_lock   <= dma_32b_r_rarb_gnt;       // offered, not taken: hold
            dma_32b_r_rarb_locked <= 1'b1;
        end
    )

    // ================================================================
    // Slave 0: ddr (32b)
    // ================================================================
    // Multi-master (2 masters) → ddr
    //   - cpu (rw)
    //   - dma (rw)

    wire cpu_32b_aw_to_ddr = (cpu_32b_aw.addr <= 32'h7fffffff);
    wire cpu_32b_ar_to_ddr = (cpu_32b_ar.addr <= 32'h7fffffff);
    wire dma_32b_aw_to_ddr = (dma_32b_aw.addr <= 32'h7fffffff);
    wire dma_32b_ar_to_ddr = (dma_32b_ar.addr <= 32'h7fffffff);

    // AW request slots for ddr: arbitration at the slave pins
    assign cpu_32b_aw_slot_ddr_in_valid = cpu_32b_aw_to_ddr && cpu_32b_awvalid && !cpu_32b_aw_hold_ddr;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_cpu_32b_aw_slot_ddr (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cpu_32b_aw_slot_ddr_in_valid), .wr_ready(cpu_32b_aw_slot_ddr_in_ready), .wr_data(cpu_32b_aw),
        .rd_valid(cpu_32b_aw_slot_ddr_valid), .rd_ready(cpu_32b_aw_slot_ddr_ready), .rd_data(cpu_32b_aw_slot_ddr),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign dma_32b_aw_slot_ddr_in_valid = dma_32b_aw_to_ddr && dma_32b_awvalid && !dma_32b_aw_hold_ddr;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_dma_32b_aw_slot_ddr (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(dma_32b_aw_slot_ddr_in_valid), .wr_ready(dma_32b_aw_slot_ddr_in_ready), .wr_data(dma_32b_aw),
        .rd_valid(dma_32b_aw_slot_ddr_valid), .rd_ready(dma_32b_aw_slot_ddr_ready), .rd_data(dma_32b_aw_slot_ddr),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );

    // ---- AW arbiter for ddr: QoS + aging, round-robin ties, lock until handshake ----
    logic [1:0] ddr_aw_arb_req;
    assign ddr_aw_arb_req = {dma_32b_aw_slot_ddr_valid, cpu_32b_aw_slot_ddr_valid};
    logic [0:0] ddr_aw_arb_lock, ddr_aw_arb_rr;
    logic ddr_aw_arb_locked;
    // QoS with aging (bridge TASK-006, was BRIDGE-017): effective priority = AxQOS + age,
    // age climbing one level every 2**4 cycles a request waits, saturating
    // at 15, cleared on grant. The highest effective priority wins; equals
    // share round-robin. A QoS-0 requester behind a QoS-15 one is served
    // after at most 15 * 2**4 cycles of waiting, never starved.
    logic [7:0] ddr_aw_arb_age_0;
    wire  [7:0] ddr_aw_arb_boost_0 = ddr_aw_arb_age_0 >> 4;
    wire  [4:0] ddr_aw_arb_sum_0 = 5'(cpu_32b_aw_slot_ddr.qos) + ((ddr_aw_arb_boost_0 > 8'd15) ? 5'd15 : 5'(ddr_aw_arb_boost_0[3:0]));
    wire  [3:0] ddr_aw_arb_eff_0 = ddr_aw_arb_sum_0[4] ? 4'hF : ddr_aw_arb_sum_0[3:0];
    wire  [3:0] ddr_aw_arb_cand_0 = ddr_aw_arb_req[0] ? ddr_aw_arb_eff_0 : 4'h0;
    logic [7:0] ddr_aw_arb_age_1;
    wire  [7:0] ddr_aw_arb_boost_1 = ddr_aw_arb_age_1 >> 4;
    wire  [4:0] ddr_aw_arb_sum_1 = 5'(dma_32b_aw_slot_ddr.qos) + ((ddr_aw_arb_boost_1 > 8'd15) ? 5'd15 : 5'(ddr_aw_arb_boost_1[3:0]));
    wire  [3:0] ddr_aw_arb_eff_1 = ddr_aw_arb_sum_1[4] ? 4'hF : ddr_aw_arb_sum_1[3:0];
    wire  [3:0] ddr_aw_arb_cand_1 = ddr_aw_arb_req[1] ? ddr_aw_arb_eff_1 : 4'h0;
    wire  [3:0] ddr_aw_arb_best = ((ddr_aw_arb_cand_1 > ddr_aw_arb_cand_0) ? ddr_aw_arb_cand_1 : ddr_aw_arb_cand_0);
    wire  [1:0] ddr_aw_arb_elig = {(ddr_aw_arb_req[1] && (ddr_aw_arb_eff_1 == ddr_aw_arb_best)), (ddr_aw_arb_req[0] && (ddr_aw_arb_eff_0 == ddr_aw_arb_best))};
    wire [0:0] ddr_aw_arb_pick = (ddr_aw_arb_rr == 1'd0) ? (ddr_aw_arb_elig[0] ? 1'd0 : 1'd1) : 
        ddr_aw_arb_elig[1] ? 1'd1 : 1'd0;
    wire ddr_aw_arb_gnt_valid = ddr_aw_arb_locked || (|ddr_aw_arb_req);
    wire [0:0] ddr_aw_arb_gnt = ddr_aw_arb_locked ? ddr_aw_arb_lock : ddr_aw_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            ddr_aw_arb_lock   <= '0;
            ddr_aw_arb_rr     <= '0;
            ddr_aw_arb_locked <= 1'b0;
            ddr_aw_arb_age_0 <= 8'd0;
            ddr_aw_arb_age_1 <= 8'd0;
        end else begin
            if (xs_ddr_axi_awvalid && xs_ddr_axi_awready) begin
                ddr_aw_arb_locked <= 1'b0;
                ddr_aw_arb_rr <= (ddr_aw_arb_gnt == 1'd1) ? 1'd0 : ddr_aw_arb_gnt + 1'b1;
            end else if (xs_ddr_axi_awvalid) begin
                ddr_aw_arb_lock   <= ddr_aw_arb_gnt;
                ddr_aw_arb_locked <= 1'b1;
            end
            if (ddr_aw_arb_gnt_valid && (ddr_aw_arb_gnt == 1'd0))
                ddr_aw_arb_age_0 <= 8'd0;
            else if (ddr_aw_arb_req[0] && (ddr_aw_arb_age_0 != 8'hFF))
                ddr_aw_arb_age_0 <= ddr_aw_arb_age_0 + 8'd1;
            if (ddr_aw_arb_gnt_valid && (ddr_aw_arb_gnt == 1'd1))
                ddr_aw_arb_age_1 <= 8'd0;
            else if (ddr_aw_arb_req[1] && (ddr_aw_arb_age_1 != 8'hFF))
                ddr_aw_arb_age_1 <= ddr_aw_arb_age_1 + 8'd1;
        end
    )
    wire cpu_32b_aw_gnt_ddr = ddr_aw_arb_gnt_valid && (ddr_aw_arb_gnt == 1'd0) && ddr_aw_arb_req[0];
    wire dma_32b_aw_gnt_ddr = ddr_aw_arb_gnt_valid && (ddr_aw_arb_gnt == 1'd1) && ddr_aw_arb_req[1];
    assign cpu_32b_aw_slot_ddr_ready = cpu_32b_aw_gnt_ddr && xs_ddr_axi_awready;
    assign dma_32b_aw_slot_ddr_ready = dma_32b_aw_gnt_ddr && xs_ddr_axi_awready;

    // AW channel (arbitrated mux across writing masters)
    assign xs_ddr_axi_awid = (cpu_32b_aw_gnt_ddr ? cpu_32b_aw_slot_ddr.id : '0) |
        (dma_32b_aw_gnt_ddr ? dma_32b_aw_slot_ddr.id : '0);
    assign xs_ddr_axi_awaddr = (cpu_32b_aw_gnt_ddr ? cpu_32b_aw_slot_ddr.addr : '0) |
        (dma_32b_aw_gnt_ddr ? dma_32b_aw_slot_ddr.addr : '0);
    assign xs_ddr_axi_awlen = (cpu_32b_aw_gnt_ddr ? cpu_32b_aw_slot_ddr.len : '0) |
        (dma_32b_aw_gnt_ddr ? dma_32b_aw_slot_ddr.len : '0);
    assign xs_ddr_axi_awsize = (cpu_32b_aw_gnt_ddr ? cpu_32b_aw_slot_ddr.size : '0) |
        (dma_32b_aw_gnt_ddr ? dma_32b_aw_slot_ddr.size : '0);
    assign xs_ddr_axi_awburst = (cpu_32b_aw_gnt_ddr ? cpu_32b_aw_slot_ddr.burst : '0) |
        (dma_32b_aw_gnt_ddr ? dma_32b_aw_slot_ddr.burst : '0);
    assign xs_ddr_axi_awlock = (cpu_32b_aw_gnt_ddr ? cpu_32b_aw_slot_ddr.lock : '0) |
        (dma_32b_aw_gnt_ddr ? dma_32b_aw_slot_ddr.lock : '0);
    assign xs_ddr_axi_awcache = (cpu_32b_aw_gnt_ddr ? cpu_32b_aw_slot_ddr.cache : '0) |
        (dma_32b_aw_gnt_ddr ? dma_32b_aw_slot_ddr.cache : '0);
    assign xs_ddr_axi_awprot = (cpu_32b_aw_gnt_ddr ? cpu_32b_aw_slot_ddr.prot : '0) |
        (dma_32b_aw_gnt_ddr ? dma_32b_aw_slot_ddr.prot : '0);
    assign xs_ddr_axi_awqos = (cpu_32b_aw_gnt_ddr ? cpu_32b_aw_slot_ddr.qos : '0) |
        (dma_32b_aw_gnt_ddr ? dma_32b_aw_slot_ddr.qos : '0);
    assign xs_ddr_axi_awregion = (cpu_32b_aw_gnt_ddr ? cpu_32b_aw_slot_ddr.region : '0) |
        (dma_32b_aw_gnt_ddr ? dma_32b_aw_slot_ddr.region : '0);
    assign xs_ddr_axi_awuser = (cpu_32b_aw_gnt_ddr ? cpu_32b_aw_slot_ddr.user : '0) |
        (dma_32b_aw_gnt_ddr ? dma_32b_aw_slot_ddr.user : '0);
    assign xs_ddr_axi_awvalid = cpu_32b_aw_gnt_ddr || dma_32b_aw_gnt_ddr;

    // W owner FIFO: slave-side AW pick order owns the W channel
    // (16 deep: max_outstanding 16)
    logic [0:0] ddr_wowner_mem [16];
    logic [4:0] ddr_wowner_wptr, ddr_wowner_rptr;
    logic ddr_wowner_ahead;
    wire ddr_wowner_valid = (ddr_wowner_wptr != ddr_wowner_rptr);
    wire ddr_wowner_byp = !ddr_wowner_valid && !ddr_wowner_ahead && xs_ddr_axi_awvalid;
    wire ddr_wowner_aw_hs = xs_ddr_axi_awvalid && xs_ddr_axi_awready;
    wire ddr_wowner_w_end = xs_ddr_axi_wvalid && xs_ddr_axi_wready && xs_ddr_axi_wlast;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            ddr_wowner_wptr  <= '0;
            ddr_wowner_rptr  <= '0;
            ddr_wowner_ahead <= 1'b0;
        end else begin
            if (ddr_wowner_aw_hs && ddr_wowner_ahead) begin
                ddr_wowner_ahead <= 1'b0;   // its W already went
            end else if (ddr_wowner_aw_hs && !(ddr_wowner_byp && ddr_wowner_w_end)) begin
                ddr_wowner_mem[ddr_wowner_wptr[3:0]] <= ddr_aw_arb_gnt;
                ddr_wowner_wptr <= ddr_wowner_wptr + 1'b1;
            end else if (!ddr_wowner_aw_hs && ddr_wowner_byp && ddr_wowner_w_end) begin
                ddr_wowner_ahead <= 1'b1;
            end
            if (ddr_wowner_valid && ddr_wowner_w_end) begin
                ddr_wowner_rptr <= ddr_wowner_rptr + 1'b1;
            end
        end
    )
    wire [0:0] ddr_wowner_head = ddr_wowner_valid ? ddr_wowner_mem[ddr_wowner_rptr[3:0]]
                                       : ddr_aw_arb_gnt;
    assign cpu_32b_w_sel_ddr = (ddr_wowner_valid || ddr_wowner_byp) && (ddr_wowner_head == 1'd0) && cpu_32b_w_to_ddr;
    assign dma_32b_w_sel_ddr = (ddr_wowner_valid || ddr_wowner_byp) && (ddr_wowner_head == 1'd1) && dma_32b_w_to_ddr;

    // W channel (owner-gated mux across writing masters)
    assign xs_ddr_axi_wdata = ((cpu_32b_w_sel_ddr && cpu_32b_wvalid) ? cpu_32b_w.data : '0) |
        ((dma_32b_w_sel_ddr && dma_32b_wvalid) ? dma_32b_w.data : '0);
    assign xs_ddr_axi_wstrb = ((cpu_32b_w_sel_ddr && cpu_32b_wvalid) ? cpu_32b_w.strb : '0) |
        ((dma_32b_w_sel_ddr && dma_32b_wvalid) ? dma_32b_w.strb : '0);
    assign xs_ddr_axi_wlast = ((cpu_32b_w_sel_ddr && cpu_32b_wvalid) ? cpu_32b_w.last : '0) |
        ((dma_32b_w_sel_ddr && dma_32b_wvalid) ? dma_32b_w.last : '0);
    assign xs_ddr_axi_wuser = ((cpu_32b_w_sel_ddr && cpu_32b_wvalid) ? cpu_32b_w.user : '0) |
        ((dma_32b_w_sel_ddr && dma_32b_wvalid) ? dma_32b_w.user : '0);
    assign xs_ddr_axi_wvalid = (cpu_32b_w_sel_ddr && cpu_32b_wvalid) || (dma_32b_w_sel_ddr && dma_32b_wvalid);

    // Bready (slave -> the master whose response arbiter granted it)
    assign xs_ddr_axi_bready = (cpu_32b_b_rgnt_ddr ? cpu_32b_bready : '0) |
        (dma_32b_b_rgnt_ddr ? dma_32b_bready : '0);

    // Bridge ID (writes) — the granted master's id
    assign xs_ddr_axi_bridge_id_aw = (cpu_32b_aw_gnt_ddr ? cpu_bridge_id_aw : '0) |
        (dma_32b_aw_gnt_ddr ? dma_bridge_id_aw : '0);

    // AR request slots for ddr: arbitration at the slave pins
    assign cpu_32b_ar_slot_ddr_in_valid = cpu_32b_ar_to_ddr && cpu_32b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_cpu_32b_ar_slot_ddr (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cpu_32b_ar_slot_ddr_in_valid), .wr_ready(cpu_32b_ar_slot_ddr_in_ready), .wr_data(cpu_32b_ar),
        .rd_valid(cpu_32b_ar_slot_ddr_valid), .rd_ready(cpu_32b_ar_slot_ddr_ready), .rd_data(cpu_32b_ar_slot_ddr),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign dma_32b_ar_slot_ddr_in_valid = dma_32b_ar_to_ddr && dma_32b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_dma_32b_ar_slot_ddr (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(dma_32b_ar_slot_ddr_in_valid), .wr_ready(dma_32b_ar_slot_ddr_in_ready), .wr_data(dma_32b_ar),
        .rd_valid(dma_32b_ar_slot_ddr_valid), .rd_ready(dma_32b_ar_slot_ddr_ready), .rd_data(dma_32b_ar_slot_ddr),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );

    // ---- AR arbiter for ddr: QoS + aging, round-robin ties, lock until handshake ----
    logic [1:0] ddr_ar_arb_req;
    assign ddr_ar_arb_req = {dma_32b_ar_slot_ddr_valid, cpu_32b_ar_slot_ddr_valid};
    logic [0:0] ddr_ar_arb_lock, ddr_ar_arb_rr;
    logic ddr_ar_arb_locked;
    // QoS with aging (bridge TASK-006, was BRIDGE-017): effective priority = AxQOS + age,
    // age climbing one level every 2**4 cycles a request waits, saturating
    // at 15, cleared on grant. The highest effective priority wins; equals
    // share round-robin. A QoS-0 requester behind a QoS-15 one is served
    // after at most 15 * 2**4 cycles of waiting, never starved.
    logic [7:0] ddr_ar_arb_age_0;
    wire  [7:0] ddr_ar_arb_boost_0 = ddr_ar_arb_age_0 >> 4;
    wire  [4:0] ddr_ar_arb_sum_0 = 5'(cpu_32b_ar_slot_ddr.qos) + ((ddr_ar_arb_boost_0 > 8'd15) ? 5'd15 : 5'(ddr_ar_arb_boost_0[3:0]));
    wire  [3:0] ddr_ar_arb_eff_0 = ddr_ar_arb_sum_0[4] ? 4'hF : ddr_ar_arb_sum_0[3:0];
    wire  [3:0] ddr_ar_arb_cand_0 = ddr_ar_arb_req[0] ? ddr_ar_arb_eff_0 : 4'h0;
    logic [7:0] ddr_ar_arb_age_1;
    wire  [7:0] ddr_ar_arb_boost_1 = ddr_ar_arb_age_1 >> 4;
    wire  [4:0] ddr_ar_arb_sum_1 = 5'(dma_32b_ar_slot_ddr.qos) + ((ddr_ar_arb_boost_1 > 8'd15) ? 5'd15 : 5'(ddr_ar_arb_boost_1[3:0]));
    wire  [3:0] ddr_ar_arb_eff_1 = ddr_ar_arb_sum_1[4] ? 4'hF : ddr_ar_arb_sum_1[3:0];
    wire  [3:0] ddr_ar_arb_cand_1 = ddr_ar_arb_req[1] ? ddr_ar_arb_eff_1 : 4'h0;
    wire  [3:0] ddr_ar_arb_best = ((ddr_ar_arb_cand_1 > ddr_ar_arb_cand_0) ? ddr_ar_arb_cand_1 : ddr_ar_arb_cand_0);
    wire  [1:0] ddr_ar_arb_elig = {(ddr_ar_arb_req[1] && (ddr_ar_arb_eff_1 == ddr_ar_arb_best)), (ddr_ar_arb_req[0] && (ddr_ar_arb_eff_0 == ddr_ar_arb_best))};
    wire [0:0] ddr_ar_arb_pick = (ddr_ar_arb_rr == 1'd0) ? (ddr_ar_arb_elig[0] ? 1'd0 : 1'd1) : 
        ddr_ar_arb_elig[1] ? 1'd1 : 1'd0;
    wire ddr_ar_arb_gnt_valid = ddr_ar_arb_locked || (|ddr_ar_arb_req);
    wire [0:0] ddr_ar_arb_gnt = ddr_ar_arb_locked ? ddr_ar_arb_lock : ddr_ar_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            ddr_ar_arb_lock   <= '0;
            ddr_ar_arb_rr     <= '0;
            ddr_ar_arb_locked <= 1'b0;
            ddr_ar_arb_age_0 <= 8'd0;
            ddr_ar_arb_age_1 <= 8'd0;
        end else begin
            if (xs_ddr_axi_arvalid && xs_ddr_axi_arready) begin
                ddr_ar_arb_locked <= 1'b0;
                ddr_ar_arb_rr <= (ddr_ar_arb_gnt == 1'd1) ? 1'd0 : ddr_ar_arb_gnt + 1'b1;
            end else if (xs_ddr_axi_arvalid) begin
                ddr_ar_arb_lock   <= ddr_ar_arb_gnt;
                ddr_ar_arb_locked <= 1'b1;
            end
            if (ddr_ar_arb_gnt_valid && (ddr_ar_arb_gnt == 1'd0))
                ddr_ar_arb_age_0 <= 8'd0;
            else if (ddr_ar_arb_req[0] && (ddr_ar_arb_age_0 != 8'hFF))
                ddr_ar_arb_age_0 <= ddr_ar_arb_age_0 + 8'd1;
            if (ddr_ar_arb_gnt_valid && (ddr_ar_arb_gnt == 1'd1))
                ddr_ar_arb_age_1 <= 8'd0;
            else if (ddr_ar_arb_req[1] && (ddr_ar_arb_age_1 != 8'hFF))
                ddr_ar_arb_age_1 <= ddr_ar_arb_age_1 + 8'd1;
        end
    )
    wire cpu_32b_ar_gnt_ddr = ddr_ar_arb_gnt_valid && (ddr_ar_arb_gnt == 1'd0) && ddr_ar_arb_req[0];
    wire dma_32b_ar_gnt_ddr = ddr_ar_arb_gnt_valid && (ddr_ar_arb_gnt == 1'd1) && ddr_ar_arb_req[1];
    assign cpu_32b_ar_slot_ddr_ready = cpu_32b_ar_gnt_ddr && xs_ddr_axi_arready;
    assign dma_32b_ar_slot_ddr_ready = dma_32b_ar_gnt_ddr && xs_ddr_axi_arready;

    // AR channel (arbitrated mux across reading masters)
    assign xs_ddr_axi_arid = (cpu_32b_ar_gnt_ddr ? cpu_32b_ar_slot_ddr.id : '0) |
        (dma_32b_ar_gnt_ddr ? dma_32b_ar_slot_ddr.id : '0);
    assign xs_ddr_axi_araddr = (cpu_32b_ar_gnt_ddr ? cpu_32b_ar_slot_ddr.addr : '0) |
        (dma_32b_ar_gnt_ddr ? dma_32b_ar_slot_ddr.addr : '0);
    assign xs_ddr_axi_arlen = (cpu_32b_ar_gnt_ddr ? cpu_32b_ar_slot_ddr.len : '0) |
        (dma_32b_ar_gnt_ddr ? dma_32b_ar_slot_ddr.len : '0);
    assign xs_ddr_axi_arsize = (cpu_32b_ar_gnt_ddr ? cpu_32b_ar_slot_ddr.size : '0) |
        (dma_32b_ar_gnt_ddr ? dma_32b_ar_slot_ddr.size : '0);
    assign xs_ddr_axi_arburst = (cpu_32b_ar_gnt_ddr ? cpu_32b_ar_slot_ddr.burst : '0) |
        (dma_32b_ar_gnt_ddr ? dma_32b_ar_slot_ddr.burst : '0);
    assign xs_ddr_axi_arlock = (cpu_32b_ar_gnt_ddr ? cpu_32b_ar_slot_ddr.lock : '0) |
        (dma_32b_ar_gnt_ddr ? dma_32b_ar_slot_ddr.lock : '0);
    assign xs_ddr_axi_arcache = (cpu_32b_ar_gnt_ddr ? cpu_32b_ar_slot_ddr.cache : '0) |
        (dma_32b_ar_gnt_ddr ? dma_32b_ar_slot_ddr.cache : '0);
    assign xs_ddr_axi_arprot = (cpu_32b_ar_gnt_ddr ? cpu_32b_ar_slot_ddr.prot : '0) |
        (dma_32b_ar_gnt_ddr ? dma_32b_ar_slot_ddr.prot : '0);
    assign xs_ddr_axi_arqos = (cpu_32b_ar_gnt_ddr ? cpu_32b_ar_slot_ddr.qos : '0) |
        (dma_32b_ar_gnt_ddr ? dma_32b_ar_slot_ddr.qos : '0);
    assign xs_ddr_axi_arregion = (cpu_32b_ar_gnt_ddr ? cpu_32b_ar_slot_ddr.region : '0) |
        (dma_32b_ar_gnt_ddr ? dma_32b_ar_slot_ddr.region : '0);
    assign xs_ddr_axi_aruser = (cpu_32b_ar_gnt_ddr ? cpu_32b_ar_slot_ddr.user : '0) |
        (dma_32b_ar_gnt_ddr ? dma_32b_ar_slot_ddr.user : '0);
    assign xs_ddr_axi_arvalid = cpu_32b_ar_gnt_ddr || dma_32b_ar_gnt_ddr;

    // Rready (slave -> the master whose response arbiter granted it)
    assign xs_ddr_axi_rready = (cpu_32b_r_rgnt_ddr ? cpu_32b_rready : '0) |
        (dma_32b_r_rgnt_ddr ? dma_32b_rready : '0);

    // Bridge ID (reads) — the granted master's id
    assign xs_ddr_axi_bridge_id_ar = (cpu_32b_ar_gnt_ddr ? cpu_bridge_id_ar : '0) |
        (dma_32b_ar_gnt_ddr ? dma_bridge_id_ar : '0);


    // ================================================================
    // Slave 1: sram (32b)
    // ================================================================
    // Multi-master (2 masters) → sram
    //   - cpu (rw)
    //   - dma (rw)

    wire cpu_32b_aw_to_sram = (cpu_32b_aw.addr >= 32'h80000000);
    wire cpu_32b_ar_to_sram = (cpu_32b_ar.addr >= 32'h80000000);
    wire dma_32b_aw_to_sram = (dma_32b_aw.addr >= 32'h80000000);
    wire dma_32b_ar_to_sram = (dma_32b_ar.addr >= 32'h80000000);

    // AW request slots for sram: arbitration at the slave pins
    assign cpu_32b_aw_slot_sram_in_valid = cpu_32b_aw_to_sram && cpu_32b_awvalid && !cpu_32b_aw_hold_sram;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_cpu_32b_aw_slot_sram (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cpu_32b_aw_slot_sram_in_valid), .wr_ready(cpu_32b_aw_slot_sram_in_ready), .wr_data(cpu_32b_aw),
        .rd_valid(cpu_32b_aw_slot_sram_valid), .rd_ready(cpu_32b_aw_slot_sram_ready), .rd_data(cpu_32b_aw_slot_sram),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign dma_32b_aw_slot_sram_in_valid = dma_32b_aw_to_sram && dma_32b_awvalid && !dma_32b_aw_hold_sram;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_dma_32b_aw_slot_sram (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(dma_32b_aw_slot_sram_in_valid), .wr_ready(dma_32b_aw_slot_sram_in_ready), .wr_data(dma_32b_aw),
        .rd_valid(dma_32b_aw_slot_sram_valid), .rd_ready(dma_32b_aw_slot_sram_ready), .rd_data(dma_32b_aw_slot_sram),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );

    // ---- AW arbiter for sram: QoS + aging, round-robin ties, lock until handshake ----
    logic [1:0] sram_aw_arb_req;
    assign sram_aw_arb_req = {dma_32b_aw_slot_sram_valid, cpu_32b_aw_slot_sram_valid};
    logic [0:0] sram_aw_arb_lock, sram_aw_arb_rr;
    logic sram_aw_arb_locked;
    // QoS with aging (bridge TASK-006, was BRIDGE-017): effective priority = AxQOS + age,
    // age climbing one level every 2**4 cycles a request waits, saturating
    // at 15, cleared on grant. The highest effective priority wins; equals
    // share round-robin. A QoS-0 requester behind a QoS-15 one is served
    // after at most 15 * 2**4 cycles of waiting, never starved.
    logic [7:0] sram_aw_arb_age_0;
    wire  [7:0] sram_aw_arb_boost_0 = sram_aw_arb_age_0 >> 4;
    wire  [4:0] sram_aw_arb_sum_0 = 5'(cpu_32b_aw_slot_sram.qos) + ((sram_aw_arb_boost_0 > 8'd15) ? 5'd15 : 5'(sram_aw_arb_boost_0[3:0]));
    wire  [3:0] sram_aw_arb_eff_0 = sram_aw_arb_sum_0[4] ? 4'hF : sram_aw_arb_sum_0[3:0];
    wire  [3:0] sram_aw_arb_cand_0 = sram_aw_arb_req[0] ? sram_aw_arb_eff_0 : 4'h0;
    logic [7:0] sram_aw_arb_age_1;
    wire  [7:0] sram_aw_arb_boost_1 = sram_aw_arb_age_1 >> 4;
    wire  [4:0] sram_aw_arb_sum_1 = 5'(dma_32b_aw_slot_sram.qos) + ((sram_aw_arb_boost_1 > 8'd15) ? 5'd15 : 5'(sram_aw_arb_boost_1[3:0]));
    wire  [3:0] sram_aw_arb_eff_1 = sram_aw_arb_sum_1[4] ? 4'hF : sram_aw_arb_sum_1[3:0];
    wire  [3:0] sram_aw_arb_cand_1 = sram_aw_arb_req[1] ? sram_aw_arb_eff_1 : 4'h0;
    wire  [3:0] sram_aw_arb_best = ((sram_aw_arb_cand_1 > sram_aw_arb_cand_0) ? sram_aw_arb_cand_1 : sram_aw_arb_cand_0);
    wire  [1:0] sram_aw_arb_elig = {(sram_aw_arb_req[1] && (sram_aw_arb_eff_1 == sram_aw_arb_best)), (sram_aw_arb_req[0] && (sram_aw_arb_eff_0 == sram_aw_arb_best))};
    wire [0:0] sram_aw_arb_pick = (sram_aw_arb_rr == 1'd0) ? (sram_aw_arb_elig[0] ? 1'd0 : 1'd1) : 
        sram_aw_arb_elig[1] ? 1'd1 : 1'd0;
    wire sram_aw_arb_gnt_valid = sram_aw_arb_locked || (|sram_aw_arb_req);
