    wire  [7:0] subtractive_aw_arb_boost_1 = subtractive_aw_arb_age_1 >> 4;
    wire  [4:0] subtractive_aw_arb_sum_1 = 5'(dma_32b_aw_slot_subtractive.qos) + ((subtractive_aw_arb_boost_1 > 8'd15) ? 5'd15 : 5'(subtractive_aw_arb_boost_1[3:0]));
    wire  [3:0] subtractive_aw_arb_eff_1 = subtractive_aw_arb_sum_1[4] ? 4'hF : subtractive_aw_arb_sum_1[3:0];
    wire  [3:0] subtractive_aw_arb_cand_1 = subtractive_aw_arb_req[1] ? subtractive_aw_arb_eff_1 : 4'h0;
    wire  [3:0] subtractive_aw_arb_best = ((subtractive_aw_arb_cand_1 > subtractive_aw_arb_cand_0) ? subtractive_aw_arb_cand_1 : subtractive_aw_arb_cand_0);
    wire  [1:0] subtractive_aw_arb_elig = {(subtractive_aw_arb_req[1] && (subtractive_aw_arb_eff_1 == subtractive_aw_arb_best)), (subtractive_aw_arb_req[0] && (subtractive_aw_arb_eff_0 == subtractive_aw_arb_best))};
    wire [0:0] subtractive_aw_arb_pick = (subtractive_aw_arb_rr == 1'd0) ? (subtractive_aw_arb_elig[0] ? 1'd0 : 1'd1) : 
        subtractive_aw_arb_elig[1] ? 1'd1 : 1'd0;
    wire subtractive_aw_arb_gnt_valid = subtractive_aw_arb_locked || (|subtractive_aw_arb_req);
    wire [0:0] subtractive_aw_arb_gnt = subtractive_aw_arb_locked ? subtractive_aw_arb_lock : subtractive_aw_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            subtractive_aw_arb_lock   <= '0;
            subtractive_aw_arb_rr     <= '0;
            subtractive_aw_arb_locked <= 1'b0;
            subtractive_aw_arb_age_0 <= 8'd0;
            subtractive_aw_arb_age_1 <= 8'd0;
        end else begin
            if (xs_subtractive_axi_awvalid && xs_subtractive_axi_awready) begin
                subtractive_aw_arb_locked <= 1'b0;
                subtractive_aw_arb_rr <= (subtractive_aw_arb_gnt == 1'd1) ? 1'd0 : subtractive_aw_arb_gnt + 1'b1;
            end else if (xs_subtractive_axi_awvalid) begin
                subtractive_aw_arb_lock   <= subtractive_aw_arb_gnt;
                subtractive_aw_arb_locked <= 1'b1;
            end
            if (subtractive_aw_arb_gnt_valid && (subtractive_aw_arb_gnt == 1'd0))
                subtractive_aw_arb_age_0 <= 8'd0;
            else if (subtractive_aw_arb_req[0] && (subtractive_aw_arb_age_0 != 8'hFF))
                subtractive_aw_arb_age_0 <= subtractive_aw_arb_age_0 + 8'd1;
            if (subtractive_aw_arb_gnt_valid && (subtractive_aw_arb_gnt == 1'd1))
                subtractive_aw_arb_age_1 <= 8'd0;
            else if (subtractive_aw_arb_req[1] && (subtractive_aw_arb_age_1 != 8'hFF))
                subtractive_aw_arb_age_1 <= subtractive_aw_arb_age_1 + 8'd1;
        end
    )
    wire cpu_32b_aw_gnt_subtractive = subtractive_aw_arb_gnt_valid && (subtractive_aw_arb_gnt == 1'd0) && subtractive_aw_arb_req[0];
    wire dma_32b_aw_gnt_subtractive = subtractive_aw_arb_gnt_valid && (subtractive_aw_arb_gnt == 1'd1) && subtractive_aw_arb_req[1];
    assign cpu_32b_aw_slot_subtractive_ready = cpu_32b_aw_gnt_subtractive && xs_subtractive_axi_awready;
    assign dma_32b_aw_slot_subtractive_ready = dma_32b_aw_gnt_subtractive && xs_subtractive_axi_awready;

    // AW channel (arbitrated mux across writing masters)
    assign xs_subtractive_axi_awid = (cpu_32b_aw_gnt_subtractive ? cpu_32b_aw_slot_subtractive.id : '0) |
        (dma_32b_aw_gnt_subtractive ? dma_32b_aw_slot_subtractive.id : '0);
    assign xs_subtractive_axi_awaddr = (cpu_32b_aw_gnt_subtractive ? cpu_32b_aw_slot_subtractive.addr : '0) |
        (dma_32b_aw_gnt_subtractive ? dma_32b_aw_slot_subtractive.addr : '0);
    assign xs_subtractive_axi_awlen = (cpu_32b_aw_gnt_subtractive ? cpu_32b_aw_slot_subtractive.len : '0) |
        (dma_32b_aw_gnt_subtractive ? dma_32b_aw_slot_subtractive.len : '0);
    assign xs_subtractive_axi_awsize = (cpu_32b_aw_gnt_subtractive ? cpu_32b_aw_slot_subtractive.size : '0) |
        (dma_32b_aw_gnt_subtractive ? dma_32b_aw_slot_subtractive.size : '0);
    assign xs_subtractive_axi_awburst = (cpu_32b_aw_gnt_subtractive ? cpu_32b_aw_slot_subtractive.burst : '0) |
        (dma_32b_aw_gnt_subtractive ? dma_32b_aw_slot_subtractive.burst : '0);
    assign xs_subtractive_axi_awlock = (cpu_32b_aw_gnt_subtractive ? cpu_32b_aw_slot_subtractive.lock : '0) |
        (dma_32b_aw_gnt_subtractive ? dma_32b_aw_slot_subtractive.lock : '0);
    assign xs_subtractive_axi_awcache = (cpu_32b_aw_gnt_subtractive ? cpu_32b_aw_slot_subtractive.cache : '0) |
        (dma_32b_aw_gnt_subtractive ? dma_32b_aw_slot_subtractive.cache : '0);
    assign xs_subtractive_axi_awprot = (cpu_32b_aw_gnt_subtractive ? cpu_32b_aw_slot_subtractive.prot : '0) |
        (dma_32b_aw_gnt_subtractive ? dma_32b_aw_slot_subtractive.prot : '0);
    assign xs_subtractive_axi_awqos = (cpu_32b_aw_gnt_subtractive ? cpu_32b_aw_slot_subtractive.qos : '0) |
        (dma_32b_aw_gnt_subtractive ? dma_32b_aw_slot_subtractive.qos : '0);
    assign xs_subtractive_axi_awregion = (cpu_32b_aw_gnt_subtractive ? cpu_32b_aw_slot_subtractive.region : '0) |
        (dma_32b_aw_gnt_subtractive ? dma_32b_aw_slot_subtractive.region : '0);
    assign xs_subtractive_axi_awuser = (cpu_32b_aw_gnt_subtractive ? cpu_32b_aw_slot_subtractive.user : '0) |
        (dma_32b_aw_gnt_subtractive ? dma_32b_aw_slot_subtractive.user : '0);
    assign xs_subtractive_axi_awvalid = cpu_32b_aw_gnt_subtractive || dma_32b_aw_gnt_subtractive;

    // W owner FIFO: slave-side AW pick order owns the W channel
    // (16 deep: max_outstanding 16)
    logic [0:0] subtractive_wowner_mem [16];
    logic [4:0] subtractive_wowner_wptr, subtractive_wowner_rptr;
    logic subtractive_wowner_ahead;
    wire subtractive_wowner_valid = (subtractive_wowner_wptr != subtractive_wowner_rptr);
    wire subtractive_wowner_byp = !subtractive_wowner_valid && !subtractive_wowner_ahead && xs_subtractive_axi_awvalid;
    wire subtractive_wowner_aw_hs = xs_subtractive_axi_awvalid && xs_subtractive_axi_awready;
    wire subtractive_wowner_w_end = xs_subtractive_axi_wvalid && xs_subtractive_axi_wready && xs_subtractive_axi_wlast;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            subtractive_wowner_wptr  <= '0;
            subtractive_wowner_rptr  <= '0;
            subtractive_wowner_ahead <= 1'b0;
        end else begin
            if (subtractive_wowner_aw_hs && subtractive_wowner_ahead) begin
                subtractive_wowner_ahead <= 1'b0;   // its W already went
            end else if (subtractive_wowner_aw_hs && !(subtractive_wowner_byp && subtractive_wowner_w_end)) begin
                subtractive_wowner_mem[subtractive_wowner_wptr[3:0]] <= subtractive_aw_arb_gnt;
                subtractive_wowner_wptr <= subtractive_wowner_wptr + 1'b1;
            end else if (!subtractive_wowner_aw_hs && subtractive_wowner_byp && subtractive_wowner_w_end) begin
                subtractive_wowner_ahead <= 1'b1;
            end
            if (subtractive_wowner_valid && subtractive_wowner_w_end) begin
                subtractive_wowner_rptr <= subtractive_wowner_rptr + 1'b1;
            end
        end
    )
    wire [0:0] subtractive_wowner_head = subtractive_wowner_valid ? subtractive_wowner_mem[subtractive_wowner_rptr[3:0]]
                                       : subtractive_aw_arb_gnt;
    assign cpu_32b_w_sel_subtractive = (subtractive_wowner_valid || subtractive_wowner_byp) && (subtractive_wowner_head == 1'd0) && cpu_32b_w_to_subtractive;
    assign dma_32b_w_sel_subtractive = (subtractive_wowner_valid || subtractive_wowner_byp) && (subtractive_wowner_head == 1'd1) && dma_32b_w_to_subtractive;

    // W channel (owner-gated mux across writing masters)
    assign xs_subtractive_axi_wdata = ((cpu_32b_w_sel_subtractive && cpu_32b_wvalid) ? cpu_32b_w.data : '0) |
        ((dma_32b_w_sel_subtractive && dma_32b_wvalid) ? dma_32b_w.data : '0);
    assign xs_subtractive_axi_wstrb = ((cpu_32b_w_sel_subtractive && cpu_32b_wvalid) ? cpu_32b_w.strb : '0) |
        ((dma_32b_w_sel_subtractive && dma_32b_wvalid) ? dma_32b_w.strb : '0);
    assign xs_subtractive_axi_wlast = ((cpu_32b_w_sel_subtractive && cpu_32b_wvalid) ? cpu_32b_w.last : '0) |
        ((dma_32b_w_sel_subtractive && dma_32b_wvalid) ? dma_32b_w.last : '0);
    assign xs_subtractive_axi_wuser = ((cpu_32b_w_sel_subtractive && cpu_32b_wvalid) ? cpu_32b_w.user : '0) |
        ((dma_32b_w_sel_subtractive && dma_32b_wvalid) ? dma_32b_w.user : '0);
    assign xs_subtractive_axi_wvalid = (cpu_32b_w_sel_subtractive && cpu_32b_wvalid) || (dma_32b_w_sel_subtractive && dma_32b_wvalid);

    // Bready (slave -> the master whose response arbiter granted it)
    assign xs_subtractive_axi_bready = (cpu_32b_b_rgnt_subtractive ? cpu_32b_bready : '0) |
        (dma_32b_b_rgnt_subtractive ? dma_32b_bready : '0);

    // Bridge ID (writes) — the granted master's id
    assign xs_subtractive_axi_bridge_id_aw = (cpu_32b_aw_gnt_subtractive ? cpu_bridge_id_aw : '0) |
        (dma_32b_aw_gnt_subtractive ? dma_bridge_id_aw : '0);

    // AR request slots for subtractive: arbitration at the slave pins
    assign cpu_32b_ar_slot_subtractive_in_valid = cpu_32b_ar_to_subtractive && cpu_32b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_cpu_32b_ar_slot_subtractive (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cpu_32b_ar_slot_subtractive_in_valid), .wr_ready(cpu_32b_ar_slot_subtractive_in_ready), .wr_data(cpu_32b_ar),
        .rd_valid(cpu_32b_ar_slot_subtractive_valid), .rd_ready(cpu_32b_ar_slot_subtractive_ready), .rd_data(cpu_32b_ar_slot_subtractive),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign dma_32b_ar_slot_subtractive_in_valid = dma_32b_ar_to_subtractive && dma_32b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_dma_32b_ar_slot_subtractive (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(dma_32b_ar_slot_subtractive_in_valid), .wr_ready(dma_32b_ar_slot_subtractive_in_ready), .wr_data(dma_32b_ar),
        .rd_valid(dma_32b_ar_slot_subtractive_valid), .rd_ready(dma_32b_ar_slot_subtractive_ready), .rd_data(dma_32b_ar_slot_subtractive),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );

    // ---- AR arbiter for subtractive: QoS + aging, round-robin ties, lock until handshake ----
    logic [1:0] subtractive_ar_arb_req;
    assign subtractive_ar_arb_req = {dma_32b_ar_slot_subtractive_valid, cpu_32b_ar_slot_subtractive_valid};
    logic [0:0] subtractive_ar_arb_lock, subtractive_ar_arb_rr;
    logic subtractive_ar_arb_locked;
    // QoS with aging (bridge TASK-006, was BRIDGE-017): effective priority = AxQOS + age,
    // age climbing one level every 2**4 cycles a request waits, saturating
    // at 15, cleared on grant. The highest effective priority wins; equals
    // share round-robin. A QoS-0 requester behind a QoS-15 one is served
    // after at most 15 * 2**4 cycles of waiting, never starved.
    logic [7:0] subtractive_ar_arb_age_0;
    wire  [7:0] subtractive_ar_arb_boost_0 = subtractive_ar_arb_age_0 >> 4;
    wire  [4:0] subtractive_ar_arb_sum_0 = 5'(cpu_32b_ar_slot_subtractive.qos) + ((subtractive_ar_arb_boost_0 > 8'd15) ? 5'd15 : 5'(subtractive_ar_arb_boost_0[3:0]));
    wire  [3:0] subtractive_ar_arb_eff_0 = subtractive_ar_arb_sum_0[4] ? 4'hF : subtractive_ar_arb_sum_0[3:0];
    wire  [3:0] subtractive_ar_arb_cand_0 = subtractive_ar_arb_req[0] ? subtractive_ar_arb_eff_0 : 4'h0;
    logic [7:0] subtractive_ar_arb_age_1;
    wire  [7:0] subtractive_ar_arb_boost_1 = subtractive_ar_arb_age_1 >> 4;
    wire  [4:0] subtractive_ar_arb_sum_1 = 5'(dma_32b_ar_slot_subtractive.qos) + ((subtractive_ar_arb_boost_1 > 8'd15) ? 5'd15 : 5'(subtractive_ar_arb_boost_1[3:0]));
    wire  [3:0] subtractive_ar_arb_eff_1 = subtractive_ar_arb_sum_1[4] ? 4'hF : subtractive_ar_arb_sum_1[3:0];
    wire  [3:0] subtractive_ar_arb_cand_1 = subtractive_ar_arb_req[1] ? subtractive_ar_arb_eff_1 : 4'h0;
    wire  [3:0] subtractive_ar_arb_best = ((subtractive_ar_arb_cand_1 > subtractive_ar_arb_cand_0) ? subtractive_ar_arb_cand_1 : subtractive_ar_arb_cand_0);
    wire  [1:0] subtractive_ar_arb_elig = {(subtractive_ar_arb_req[1] && (subtractive_ar_arb_eff_1 == subtractive_ar_arb_best)), (subtractive_ar_arb_req[0] && (subtractive_ar_arb_eff_0 == subtractive_ar_arb_best))};
    wire [0:0] subtractive_ar_arb_pick = (subtractive_ar_arb_rr == 1'd0) ? (subtractive_ar_arb_elig[0] ? 1'd0 : 1'd1) : 
        subtractive_ar_arb_elig[1] ? 1'd1 : 1'd0;
    wire subtractive_ar_arb_gnt_valid = subtractive_ar_arb_locked || (|subtractive_ar_arb_req);
    wire [0:0] subtractive_ar_arb_gnt = subtractive_ar_arb_locked ? subtractive_ar_arb_lock : subtractive_ar_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            subtractive_ar_arb_lock   <= '0;
            subtractive_ar_arb_rr     <= '0;
            subtractive_ar_arb_locked <= 1'b0;
            subtractive_ar_arb_age_0 <= 8'd0;
            subtractive_ar_arb_age_1 <= 8'd0;
        end else begin
            if (xs_subtractive_axi_arvalid && xs_subtractive_axi_arready) begin
                subtractive_ar_arb_locked <= 1'b0;
                subtractive_ar_arb_rr <= (subtractive_ar_arb_gnt == 1'd1) ? 1'd0 : subtractive_ar_arb_gnt + 1'b1;
            end else if (xs_subtractive_axi_arvalid) begin
                subtractive_ar_arb_lock   <= subtractive_ar_arb_gnt;
                subtractive_ar_arb_locked <= 1'b1;
            end
            if (subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 1'd0))
                subtractive_ar_arb_age_0 <= 8'd0;
            else if (subtractive_ar_arb_req[0] && (subtractive_ar_arb_age_0 != 8'hFF))
                subtractive_ar_arb_age_0 <= subtractive_ar_arb_age_0 + 8'd1;
            if (subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 1'd1))
                subtractive_ar_arb_age_1 <= 8'd0;
            else if (subtractive_ar_arb_req[1] && (subtractive_ar_arb_age_1 != 8'hFF))
                subtractive_ar_arb_age_1 <= subtractive_ar_arb_age_1 + 8'd1;
        end
    )
    wire cpu_32b_ar_gnt_subtractive = subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 1'd0) && subtractive_ar_arb_req[0];
    wire dma_32b_ar_gnt_subtractive = subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 1'd1) && subtractive_ar_arb_req[1];
    assign cpu_32b_ar_slot_subtractive_ready = cpu_32b_ar_gnt_subtractive && xs_subtractive_axi_arready;
    assign dma_32b_ar_slot_subtractive_ready = dma_32b_ar_gnt_subtractive && xs_subtractive_axi_arready;

    // AR channel (arbitrated mux across reading masters)
    assign xs_subtractive_axi_arid = (cpu_32b_ar_gnt_subtractive ? cpu_32b_ar_slot_subtractive.id : '0) |
        (dma_32b_ar_gnt_subtractive ? dma_32b_ar_slot_subtractive.id : '0);
    assign xs_subtractive_axi_araddr = (cpu_32b_ar_gnt_subtractive ? cpu_32b_ar_slot_subtractive.addr : '0) |
        (dma_32b_ar_gnt_subtractive ? dma_32b_ar_slot_subtractive.addr : '0);
    assign xs_subtractive_axi_arlen = (cpu_32b_ar_gnt_subtractive ? cpu_32b_ar_slot_subtractive.len : '0) |
        (dma_32b_ar_gnt_subtractive ? dma_32b_ar_slot_subtractive.len : '0);
    assign xs_subtractive_axi_arsize = (cpu_32b_ar_gnt_subtractive ? cpu_32b_ar_slot_subtractive.size : '0) |
        (dma_32b_ar_gnt_subtractive ? dma_32b_ar_slot_subtractive.size : '0);
    assign xs_subtractive_axi_arburst = (cpu_32b_ar_gnt_subtractive ? cpu_32b_ar_slot_subtractive.burst : '0) |
        (dma_32b_ar_gnt_subtractive ? dma_32b_ar_slot_subtractive.burst : '0);
    assign xs_subtractive_axi_arlock = (cpu_32b_ar_gnt_subtractive ? cpu_32b_ar_slot_subtractive.lock : '0) |
        (dma_32b_ar_gnt_subtractive ? dma_32b_ar_slot_subtractive.lock : '0);
    assign xs_subtractive_axi_arcache = (cpu_32b_ar_gnt_subtractive ? cpu_32b_ar_slot_subtractive.cache : '0) |
        (dma_32b_ar_gnt_subtractive ? dma_32b_ar_slot_subtractive.cache : '0);
    assign xs_subtractive_axi_arprot = (cpu_32b_ar_gnt_subtractive ? cpu_32b_ar_slot_subtractive.prot : '0) |
        (dma_32b_ar_gnt_subtractive ? dma_32b_ar_slot_subtractive.prot : '0);
    assign xs_subtractive_axi_arqos = (cpu_32b_ar_gnt_subtractive ? cpu_32b_ar_slot_subtractive.qos : '0) |
        (dma_32b_ar_gnt_subtractive ? dma_32b_ar_slot_subtractive.qos : '0);
    assign xs_subtractive_axi_arregion = (cpu_32b_ar_gnt_subtractive ? cpu_32b_ar_slot_subtractive.region : '0) |
        (dma_32b_ar_gnt_subtractive ? dma_32b_ar_slot_subtractive.region : '0);
    assign xs_subtractive_axi_aruser = (cpu_32b_ar_gnt_subtractive ? cpu_32b_ar_slot_subtractive.user : '0) |
        (dma_32b_ar_gnt_subtractive ? dma_32b_ar_slot_subtractive.user : '0);
    assign xs_subtractive_axi_arvalid = cpu_32b_ar_gnt_subtractive || dma_32b_ar_gnt_subtractive;

    // Rready (slave -> the master whose response arbiter granted it)
    assign xs_subtractive_axi_rready = (cpu_32b_r_rgnt_subtractive ? cpu_32b_rready : '0) |
        (dma_32b_r_rgnt_subtractive ? dma_32b_rready : '0);

    // Bridge ID (reads) — the granted master's id
    assign xs_subtractive_axi_bridge_id_ar = (cpu_32b_ar_gnt_subtractive ? cpu_bridge_id_ar : '0) |
        (dma_32b_ar_gnt_subtractive ? dma_bridge_id_ar : '0);


    // ================================================================
    // W destination FIFOs (per master width-path)
    // ================================================================
    // cpu 32b path -> ddr, sram, subtractive (16 deep: max_outstanding)
    logic [1:0] cpu_32b_wdest_mem [16];
    logic [4:0] cpu_32b_wdest_wptr, cpu_32b_wdest_rptr;
    wire [1:0] cpu_32b_wdest_enc = cpu_32b_aw_to_sram ? 2'd1 : cpu_32b_aw_to_subtractive ? 2'd2 : 2'd0;
    wire cpu_32b_wdest_push = cpu_32b_awvalid && cpu_32b_awready;
    wire cpu_32b_wdest_pop  = cpu_32b_wvalid && cpu_32b_wready && cpu_32b_w.last;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            cpu_32b_wdest_wptr <= '0;
            cpu_32b_wdest_rptr <= '0;
        end else begin
            if (cpu_32b_wdest_push) begin
                cpu_32b_wdest_mem[cpu_32b_wdest_wptr[3:0]] <= cpu_32b_wdest_enc;
                cpu_32b_wdest_wptr <= cpu_32b_wdest_wptr + 1'b1;
            end
            if (cpu_32b_wdest_pop) begin
                cpu_32b_wdest_rptr <= cpu_32b_wdest_rptr + 1'b1;
            end
        end
    )
    wire cpu_32b_wdest_valid = (cpu_32b_wdest_wptr != cpu_32b_wdest_rptr);
    wire [1:0] cpu_32b_wdest_head = cpu_32b_wdest_mem[cpu_32b_wdest_rptr[3:0]];
    assign cpu_32b_w_to_ddr = cpu_32b_wdest_valid && (cpu_32b_wdest_head == 2'd0);
    assign cpu_32b_w_to_sram = cpu_32b_wdest_valid && (cpu_32b_wdest_head == 2'd1);
    assign cpu_32b_w_to_subtractive = cpu_32b_wdest_valid && (cpu_32b_wdest_head == 2'd2);

    // dma 32b path -> ddr, sram, subtractive (16 deep: max_outstanding)
    logic [1:0] dma_32b_wdest_mem [16];
    logic [4:0] dma_32b_wdest_wptr, dma_32b_wdest_rptr;
    wire [1:0] dma_32b_wdest_enc = dma_32b_aw_to_sram ? 2'd1 : dma_32b_aw_to_subtractive ? 2'd2 : 2'd0;
    wire dma_32b_wdest_push = dma_32b_awvalid && dma_32b_awready;
